-- =============================================================
-- FlowState -- RUN_ALL.sql
-- =============================================================
-- Auto-generated by concatenating every file in migrations/ in
-- order. Every migration in this project is written to be safe
-- to re-run (create table/column/index all use IF NOT EXISTS,
-- every RLS policy is DROP POLICY IF EXISTS + CREATE POLICY, every
-- seed INSERT is guarded with ON CONFLICT or an existence check).
--
-- That means this file is always safe to paste into the Supabase
-- SQL editor and run in full, regardless of which individual
-- migrations have or haven't been applied already -- it brings the
-- database fully in sync with the repo with zero guesswork about
-- migration history. This is the fix for the recurring class of
-- bug where a migration was written but never actually run against
-- the live database (missing columns, missing RLS policies) and
-- the app failed silently or with a confusing error.
--
-- Regenerate this file any time a new migration is added:
--   cd supabase && for f in migrations/*.sql; do (echo; echo "-- ---- $f ----"; cat "$f") >> RUN_ALL.sql
-- (or just ask Claude to regenerate it)
--
-- NOTE: supabase/schema.sql is NOT included here -- it is the
-- original pre-migrations bootstrap for a generic workflow system
-- that migration 019_drop_legacy_workflows.sql deliberately tears
-- down. It is historical only; do not run it.
-- =============================================================

-- =============================================================
-- ---- migrations/004_day_planning.sql ----
-- =============================================================
-- Day planning tables: daily_tasks, daily_intentions, routine_completions
-- These replace Notion as the primary store for the day planner

create table if not exists daily_tasks (
  id              uuid primary key default gen_random_uuid(),
  title           text not null,
  due_date        date,
  status          text not null default 'Not started',
  urgency         text,
  importance      text,
  time_commitment text,
  task_type       text,
  is_frog         boolean not null default false,
  why_note        text,
  notion_id       text unique,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create table if not exists daily_intentions (
  id              uuid primary key default gen_random_uuid(),
  intention_date  date not null unique,
  intention_text  text not null default '',
  locked          boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create table if not exists routine_completions (
  id             uuid primary key default gen_random_uuid(),
  routine_date   date not null unique,
  completed_at   timestamptz not null default now()
);

create index if not exists daily_tasks_due_date_idx on daily_tasks(due_date);
create index if not exists daily_tasks_status_idx on daily_tasks(status);

create or replace function set_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end;
$$;

drop trigger if exists daily_tasks_updated_at on daily_tasks;
create trigger daily_tasks_updated_at
  before update on daily_tasks for each row execute function set_updated_at();

drop trigger if exists daily_intentions_updated_at on daily_intentions;
create trigger daily_intentions_updated_at
  before update on daily_intentions for each row execute function set_updated_at();

-- =============================================================
-- ---- migrations/005_tasks.sql ----
-- =============================================================
-- 005_tasks.sql
-- Central tasks table: authoritative store for all tasks (synced from Notion, created in-app)
-- Replaces the split daily_tasks + Notion API approach.
--
-- Guard: an older, incompatible "tasks" table can already exist on the live
-- database from the original schema.sql (the legacy generic-workflow system,
-- with stage_id/instructions columns and no "archived" column). If it's still
-- there, "create table if not exists" below is a no-op against it and the
-- indexes further down fail with "column archived does not exist". That
-- legacy table is unconditionally dropped later anyway (019_drop_legacy_workflows.sql,
-- superseded by master_tasks from 010_master_tasks.sql), so it's always safe
-- to drop it here too rather than let this migration fail on old data.
do $$
begin
  if to_regclass('public.tasks') is not null
     and not exists (
       select 1 from information_schema.columns
       where table_name = 'tasks' and column_name = 'archived'
     )
  then
    drop table tasks cascade;
  end if;
end $$;

create table if not exists tasks (
  id               uuid        primary key default gen_random_uuid(),
  notion_id        text        unique,                          -- deduplication key for Notion sync
  title            text        not null,
  status           text        not null default 'Not started', -- 'Not started' | 'In progress' | 'Done'
  due_date         date,
  task_type        text,                                        -- 'Flow' | 'Recurring' | 'Quick Task' | 'Admin' | 'Personal'
  urgency          text,                                        -- 'Urgent' | 'Habit' | 'Non Urgent'
  importance       text,                                        -- 'Moved the Needle' | 'Non Important' | 'Important'
  time_commitment  text,                                        -- '60 + mins' | '30 - 60 mins' | '15 - 30 mins' | '< 15mins'
  is_frog          boolean     not null default false,          -- top priority task of the day
  priority         text,                                        -- 'Low' | 'Medium' | 'High'
  why_note         text,                                        -- personal reason / motivation note
  notion_url       text,                                        -- link back to Notion page
  archived         boolean     not null default false,          -- soft delete
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- Performance indexes
create index if not exists tasks_due_date_idx
  on tasks(due_date)
  where archived = false;

create index if not exists tasks_status_idx
  on tasks(status)
  where archived = false and status != 'Done';

create index if not exists tasks_frog_idx
  on tasks(due_date, is_frog)
  where archived = false and is_frog = true;

create index if not exists tasks_type_idx
  on tasks(task_type, due_date)
  where archived = false;

-- Auto-update updated_at on every row change
create or replace function tasks_set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists tasks_updated_at on tasks;
create trigger tasks_updated_at
  before update on tasks
  for each row execute procedure tasks_set_updated_at();

-- Enable RLS (personal app -- allow all for anon key)
alter table tasks enable row level security;

drop policy if exists "allow_all_tasks" on tasks;
create policy "allow_all_tasks" on tasks
  for all using (true) with check (true);

-- =============================================================
-- ---- migrations/006_habits.sql ----
-- =============================================================
-- ============================================================
-- 006_habits.sql  —  Habit tracker
-- ============================================================

-- habits: one row per habit definition
create table if not exists habits (
  id              uuid        primary key default gen_random_uuid(),
  title           text        not null,
  description     text,
  -- schedule_type: 'daily' | 'weekdays' | 'weekends' | 'custom'
  schedule_type   text        not null default 'daily',
  -- schedule_days: array of weekday ints (0=Sun … 6=Sat) used when type='custom'
  schedule_days   integer[]   not null default '{}',
  -- optional target time 'HH:MM' — used for accountability warnings
  schedule_time   text,
  color           text        not null default '#00d4ff',
  emoji           text        not null default '✓',
  sort_order      integer     not null default 0,
  active          boolean     not null default true,
  created_at      timestamptz not null default now()
);

-- habit_completions: one row per habit per calendar day it was checked off
create table if not exists habit_completions (
  id              uuid        primary key default gen_random_uuid(),
  habit_id        uuid        not null references habits(id) on delete cascade,
  completed_date  date        not null,
  completed_at    timestamptz not null default now(),
  -- prevent duplicate completions for the same day
  unique(habit_id, completed_date)
);

-- Indexes
create index if not exists habit_completions_habit_id_idx     on habit_completions(habit_id);
create index if not exists habit_completions_date_idx         on habit_completions(completed_date);

-- Auto-updated_at is not needed for these simple tables

-- ---- RLS (open policy for personal single-user app) ----
alter table habits            enable row level security;
alter table habit_completions enable row level security;

drop policy if exists allow_all_habits            on habits;
drop policy if exists allow_all_habit_completions on habit_completions;

create policy allow_all_habits            on habits            for all using (true) with check (true);
create policy allow_all_habit_completions on habit_completions for all using (true) with check (true);

