-- =============================================================
-- ---- migrations/036_dedupe_habits.sql ----
-- =============================================================
-- 036_dedupe_habits.sql — Fix duplicate habits, make it structurally
-- impossible to happen again.
--
-- Root cause: 006_habits.sql's seed insert used "on conflict do nothing"
-- but the habits table had no unique constraint for anything to actually
-- conflict on (id is a fresh random uuid every time) -- so every time the
-- seed insert ran again (e.g. re-running RUN_ALL.sql against an already-
-- provisioned database), it silently added another full set of duplicate
-- habit rows instead of being skipped. That's why the Tracking page and
-- Home's streaks row started showing repeated habits, and why finishing
-- the Morning Routine stopped extending its Habit Tracker streak --
-- completeMorningRoutineHabit() (lib/supabase.ts) and Home's own
-- cross-check both looked the habit up by title with .maybeSingle(),
-- which errors out the moment more than one row shares that title, and
-- that error was never surfaced anywhere, so it just silently no-op'd.
--
-- This migration is idempotent and safe to re-run: for each set of
-- same-titled habit rows it keeps the oldest one, moves any completions
-- recorded against the newer duplicates onto it, deletes the duplicates,
-- then adds a real unique constraint on title so this can't recur. Once
-- re-run with no duplicates left, both statements below simply affect 0
-- rows and the CREATE UNIQUE INDEX is a no-op.

with ranked as (
  select id, title,
         first_value(id) over (partition by title order by created_at asc, id asc) as keeper_id
  from habits
),
dups as (
  select id, keeper_id from ranked where id <> keeper_id
)
insert into habit_completions (habit_id, completed_date)
select d.keeper_id, hc.completed_date
from habit_completions hc
join dups d on d.id = hc.habit_id
on conflict (habit_id, completed_date) do nothing;

with ranked as (
  select id, title,
         first_value(id) over (partition by title order by created_at asc, id asc) as keeper_id
  from habits
)
delete from habits where id in (select id from ranked where id <> keeper_id);

create unique index if not exists habits_title_unique_idx on habits(title);

-- =============================================================
-- ---- migrations/037_dedupe_weekly_targets.sql ----
-- =============================================================
-- 037_dedupe_weekly_targets.sql — Same bug as 036_dedupe_habits.sql, same
-- fix, different table. 028_weekly_targets.sql's seed insert already used
-- a bare "on conflict do nothing", but weekly_targets never had a unique
-- constraint on label -- so re-running RUN_ALL.sql kept silently adding
-- another full set of the 4 default targets. That's the "lots of empty
-- boxes" on Home's This week's targets section.

with ranked as (
  select id, label,
         first_value(id) over (partition by label order by created_at asc, id asc) as keeper_id
  from weekly_targets
),
dups as (
  select id, keeper_id from ranked where id <> keeper_id
)
insert into weekly_target_progress (target_id, week_start, manual_count, updated_at)
select d.keeper_id, wtp.week_start, wtp.manual_count, wtp.updated_at
from weekly_target_progress wtp
join dups d on d.id = wtp.target_id
on conflict (target_id, week_start) do nothing;

with ranked as (
  select id, label,
         first_value(id) over (partition by label order by created_at asc, id asc) as keeper_id
  from weekly_targets
),
dups as (
  select id, keeper_id from ranked where id <> keeper_id
)
insert into weekly_target_picks (target_id, week_start, content_item_id, updated_at)
select d.keeper_id, wtp.week_start, wtp.content_item_id, wtp.updated_at
from weekly_target_picks wtp
join dups d on d.id = wtp.target_id
on conflict (target_id, week_start) do nothing;

with ranked as (
  select id, label,
         first_value(id) over (partition by label order by created_at asc, id asc) as keeper_id
  from weekly_targets
)
delete from weekly_targets where id in (select id from ranked where id <> keeper_id);

create unique index if not exists weekly_targets_label_unique_idx on weekly_targets(label);

-- ---- migrations/038_yap_session_and_storyboard.sql ----
-- =============================================================
-- FlowState — Yap Session transcripts + Storyboard blocks
--
-- Two new per-content-item tables supporting the Scripting stage:
--
-- 1. content_yap_transcripts — one row per content item, holding the whole
--    back-and-forth "yap session" conversation (you talk out loud about the
--    video, Claude interviews you with follow-ups) as a JSON array of
--    {role, content} messages. Single row per item (primary key on
--    content_item_id) since there's only ever one running conversation per
--    video, updated in place rather than accumulating history rows.
--
-- 2. content_storyboard_blocks — many rows per content item, one per shot/
--    beat: the spoken line plus what's on screen at that moment (b-roll,
--    screenshot, animation, image, meme, text overlay, SFX, or just VO).
--    Ordered by sort_order. This is the color-coded script — reading down
--    the list is the storyboard, and counting rows by asset_type is the
--    asset checklist ("collect 4 b-roll clips, 3 screenshots...") before
--    you ever open Premiere.
--
-- RUN IN SUPABASE SQL EDITOR — safe to re-run
-- =============================================================

create table if not exists content_yap_transcripts (
  content_item_id uuid primary key references content_items(id) on delete cascade,
  messages jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

alter table content_yap_transcripts enable row level security;
drop policy if exists allow_all_content_yap_transcripts on content_yap_transcripts;
create policy allow_all_content_yap_transcripts on content_yap_transcripts for all using (true) with check (true);

create table if not exists content_storyboard_blocks (
  id uuid primary key default gen_random_uuid(),
  content_item_id uuid not null references content_items(id) on delete cascade,
  sort_order integer not null default 0,
  text text not null default '',
  -- 'vo' | 'text' | 'broll' | 'screenshot' | 'animation' | 'image' | 'meme' | 'sfx'
  asset_type text not null default 'vo',
  note text,
  created_at timestamptz not null default now()
);

create index if not exists content_storyboard_blocks_item_idx on content_storyboard_blocks(content_item_id, sort_order);

alter table content_storyboard_blocks enable row level security;
drop policy if exists allow_all_content_storyboard_blocks on content_storyboard_blocks;
create policy allow_all_content_storyboard_blocks on content_storyboard_blocks for all using (true) with check (true);
